using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class FixHud08EEscapeInput{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();var rows=new JArray();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var inputs=h.GetComponentsInChildren<TMPro.TMP_InputField>(true);foreach(var i in inputs){i.restoreOriginalTextOnEscape=false;EditorUtility.SetDirty(i);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);rows.Add(new JObject{{"scene",name},{"inputsPreserveTextOnEscape",inputs.Length}});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText("Docs/Measurements/2026-10-03-hud-08e/input-authoring.json",rows.ToString());return "Saved Esc text-preservation policy in both scenes";}}
